199	/* ---------------------------------------------------------------- */
200	/* Small helpers                                                      */
201	/* ---------------------------------------------------------------- */
202	static inline uint32_t xr_read32le(const uint8_t *b)
203	{
204		return (uint32_t)b[0] | ((uint32_t)b[1] << 8)
205				| ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
206	}
207	
208	static inline uint64_t xr_read64le(const uint8_t *b)
209	{
210		return (uint64_t)xr_read32le(b) | ((uint64_t)xr_read32le(b + 4) << 32);
211	}
212	
213	static inline void xr_write32le(uint8_t *b, uint32_t v)
214	{
215		b[0] = (uint8_t)v;
216		b[1] = (uint8_t)(v >> 8);
217		b[2] = (uint8_t)(v >> 16);
218		b[3] = (uint8_t)(v >> 24);
219	}
220	
221	static inline void xr_write64le(uint8_t *b, uint64_t v)
222	{
223		xr_write32le(b, (uint32_t)v);
224		xr_write32le(b + 4, (uint32_t)(v >> 32));
225	}
226	
227	static inline uint32_t xr_read32be(const uint8_t *b)
228	{
229		return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16)
230				| ((uint32_t)b[2] << 8) | (uint32_t)b[3];
231	}
232	
233	static inline void xr_write32be(uint8_t *b, uint32_t v)
234	{
235		b[0] = (uint8_t)(v >> 24);
236		b[1] = (uint8_t)(v >> 16);
237		b[2] = (uint8_t)(v >> 8);
238		b[3] = (uint8_t)v;
239	}
