241	/* Number of bytes a VLI takes when encoded. */
242	static inline uint32_t xr_vli_size(xr_vli v)
243	{
244		uint32_t n = 0;
245		do {
246			++n;
247			v >>= 7;
248		} while (v != 0);
249		return n;
250	}
